mapper.sql:
FROM POPUP_MST
WHERE DEL_DT IS NULL

	AND USE_YN = #{useYn}


	AND PSTG_BGNG_YMD >= #{startPublishDate}


	AND PSTG_END_YMD <= #{endPublishDate}


	AND DATE(REG_DT) >= #{startRegDate}


	AND DATE(REG_DT) <= #{endRegDate}




			AND POPUP_NM LIKE CONCAT('%', #{searchKeyword}, '%')


			AND POPUP_CN LIKE CONCAT('%', #{searchKeyword}, '%')


			AND (POPUP_NM LIKE CONCAT('%', #{searchKeyword}, '%') OR POPUP_CN LIKE CONCAT('%', #{searchKeyword}, '%'))

mapper.update:
UPDATE POPUP_MST SET
	DEL_DT = NOW(),
	DELTR = #{deltr}
WHERE POPUP_SN = #{popupSn}
AND DEL_DT IS NULL
